test('x', () => {
  const n = ref(0)
  const c = computed(() => n.value)
  const out: string[] = []
  for (let i = 0; i < 5; i++) {
    watch(n, () => out.push('n' + i), { flush: 'sync' })
  }
  for (let i = 0; i < 5; i++) {
    watch(c, () => out.push('c' + i), { flush: 'sync' })
  }
  n.value++
  console.log(out.join(' '))
})

